function parseList(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.311s.com').replace(/\/+$/, '');
  if (typeof html !== 'string' || html.length < 50) return [];
  var out = [];
  var seen = {};

  function strip(s) {
    return String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  }
  function attr(tag, name) {
    var m = tag.match(new RegExp(name + '\\s*=\\s*"([^"]*)"', 'i'));
    return m ? m[1] : '';
  }
  // 嵌套 <div> 配对切片：避免非贪婪正则在 comic-meta 处提前截断。
  function sliceBlock(src, start) {
    var depth = 1;
    var re = /<\/?div\b/gi;
    re.lastIndex = start;
    var m;
    while ((m = re.exec(src)) !== null) {
      if (m[0].charAt(1) === '/') {
        depth--;
        if (depth === 0) return src.substring(start, m.index);
      } else {
        depth++;
      }
    }
    return src.substring(start);
  }
  function push(id, title, cover, href, author, status) {
    if (!id || !title || !cover || seen[id]) return;
    seen[id] = 1;
    out.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: baseUrl + href,
      author: author || '',
      status: status || ''
    });
  }

  var openRe = /<div[^>]*class="[^"]*comic-item[^"]*"[^>]*>/gi;
  var om;
  while ((om = openRe.exec(html)) !== null) {
    var block = sliceBlock(html, om.index + om[0].length);
    var linkM = block.match(/<a[^>]+href="(\/comic_(\d+)\.html)"[^>]*>/i);
    if (!linkM) continue;
    var href = linkM[1];
    var id = linkM[2];

    var cover = '';
    var imgM = block.match(/<img[^>]+src="([^"]+)"/i);
    if (imgM) cover = imgM[1];

    var title = '';
    var h3M = block.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i);
    if (h3M) {
      var aM = h3M[1].match(/<a[^>]*title="([^"]*)"[^>]*>/i);
      if (aM) title = strip(aM[1]);
      if (!title) title = strip(h3M[1]);
    }
    if (!title && imgM) title = strip(attr(imgM[0], 'alt'));

    var author = '';
    var auM = block.match(/<p[^>]*class="[^"]*comic-author[^"]*"[^>]*>([\s\S]*?)<\/p>/i);
    if (auM) author = strip(auM[1]);

    var status = '';
    var stM = block.match(/<span[^>]*class="[^"]*update-badge[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
    if (stM) status = strip(stM[1]);

    push(id, title, cover, href, author, status);
  }

  // 兜底：页面结构变化时直接扫漫画链接
  if (out.length === 0) {
    var aRe = /<a[^>]+href="(\/comic_(\d+)\.html)"[^>]*>([\s\S]*?)<\/a>/gi;
    var am;
    while ((am = aRe.exec(html)) !== null) {
      var href2 = am[1];
      var id2 = am[2];
      var inner = am[3];
      var title2 = strip(attr(am[0], 'title'));
      if (!title2) title2 = strip(inner);
      var cover2 = '';
      var im = inner.match(/<img[^>]+src="([^"]+)"/i);
      if (im) cover2 = im[1];
      if (!title2 && im) title2 = strip(attr(im[0], 'alt'));
      if (!cover2) continue;
      push(id2, title2, cover2, href2, '', '');
    }
  }
  return out;
}

