detail.script:
function parseDetail(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.311s.com').replace(/\/+$/, '');
  if (typeof html !== 'string') html = '';
  function strip(s) {
    return String(s || '').replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#37;/g, '%').replace(/\s+/g, ' ').trim();
  }
  function decode(s) {
    return String(s || '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#37;/g, '%').replace(/&#39;/g, "'");
  }

  var title = '';
  var h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  if (h1) title = strip(h1[1]);
  if (!title) {
    var og = html.match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i) ||
             html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i);
    if (og) {
      title = strip(og[1]).split(/[_|]/)[0].replace(/全集.*$/, '');
    }
  }

  var cover = '';
  var coverBox = html.match(/<div[^>]*class="[^"]*comic-cover-large[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
  if (coverBox) {
    var ci = coverBox[1].match(/<img[^>]+src="([^"]+)"/i);
    if (ci) cover = ci[1];
  }
  if (!cover) {
    var ogi = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
              html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
    if (ogi) cover = ogi[1];
  }
  if (cover && cover.indexOf('http') !== 0) {
    cover = cover.charAt(0) === '/' ? baseUrl + cover : baseUrl + '/' + cover;
  }

  var author = '';
  var au = html.match(/<span>\s*作者[：:]\s*([^<]*)<\/span>/i) ||
           html.match(/作者[：:]\s*([^<\n]{1,30})/);
  if (au) author = strip(au[1]);

  var tags = [];
  var status = '';
  var tagBox = html.match(/<div[^>]*class="[^"]*comic-tags[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
  if (tagBox) {
    var spans = tagBox[1].match(/<span[^>]*class="[^"]*tag[^"]*"[^>]*>([\s\S]*?)<\/span>/gi) || [];
    for (var i = 0; i < spans.length; i++) {
      var t = strip(spans[i].replace(/<\/?span[^>]*>/gi, ''));
      if (!t) continue;
      if (/^(连载|完结|連載|完結)/.test(t)) {
        if (!status) status = t;
        continue;
      }
      var parts = t.split(/[\s,，、]+/);
      for (var p = 0; p < parts.length; p++) {
        if (parts[p] && tags.indexOf(parts[p]) === -1) tags.push(parts[p]);
      }
    }
  }
  if (!status) {
    var st = html.match(/<span[^>]*class="[^"]*update-badge[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
    if (st) status = strip(st[1]);
  }

  var description = '';
  var descIdx = html.indexOf('comic-description');
  if (descIdx >= 0) {
    var p = html.slice(descIdx).match(/<p[^>]*>([\s\S]*?)<\/p>/i);
    if (p) description = decode(strip(p[1]));
  }
  if (!description) {
    var md = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i);
    if (md) description = decode(strip(md[1]));
  }

  return {
    id: ctx.id || '',
    title: title,
    cover: cover,
    author: author,
    genre: tags.length > 0 ? tags[0] : '',
    tags: tags,
    status: status,
    description: description
  };
}

chapters.script:
function parseChapters(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://www.311s.com').replace(/\/+$/, '');
  if (!html || typeof html !== 'string' || html.length < 20) return [];
  function strip(s) {
    return String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  }
  var out = [];
  var seen = {};
  var re = /<a[^>]+href="\/(chapter_\d+_\d+\.html)"[^>]*>([\s\S]*?)<\/a>/gi;
  var m;
  while ((m = re.exec(html)) !== null) {
    // id 不带前导斜杠：images 路由写成 /{chapterId} 时避免拼成双斜杠坏链。
    var id = m[1];
    if (seen[id]) continue;
    var title = strip(m[2]);
    if (!title) continue;
    seen[id] = 1;
    out.push({ id: id, title: title, url: baseUrl + '/' + id, updatedAt: '' });
  }
  return out;
}

images.script:
function parseImages(html, context) {
  if (!html || typeof html !== 'string') return [];
  function sliceBlock(src, start) {
    var depth = 1;
    var re = /<\/?div\b/gi;
    re.lastIndex = start;
    var m;
    while ((m = re.exec(src)) !== null) {
      if (m[0].charAt(1) === '/') {
        depth--;
        if (depth === 0) return src.substring(start, m.index);
      } else {
        depth++;
      }
    }
    return src.substring(start);
  }
  var out = [];
  var seen = {};
  function add(u) {
    if (!u || u.indexOf('http') !== 0) return;
    if (seen[u]) return;
    var low = u.toLowerCase();
    if (low.indexOf('logo') !== -1 || low.indexOf('icon') !== -1 ||
        low.indexOf('avatar') !== -1 || low.indexOf('banner') !== -1 ||
        low.indexOf('qrcode') !== -1) return;
    seen[u] = 1;
    out.push(u);
  }

  var openRe = /<div[^>]*class="[^"]*comic-content[^"]*"[^>]*>/i;
  var om = html.match(openRe);
  if (om) {
    var idx = html.indexOf(om[0]) + om[0].length;
    var block = sliceBlock(html, idx);
    var imgRe = /<img[^>]+src="([^"]+)"/gi;
    var im;
    while ((im = imgRe.exec(block)) !== null) add(im[1]);
  }
  if (out.length === 0) {
    var gRe = /<img[^>]*class="[^"]*comic-image[^"]*"[^>]*/gi;
    var gm;
    while ((gm = gRe.exec(html)) !== null) {
      var s = gm[0].match(/src="([^"]+)"/i);
      if (s) add(s[1]);
    }
  }
  return out;
}
